def transform(grid):
    # Count frequencies to find the background color (most frequent)
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    bg = max(counts, key=counts.get) if counts else 0

    # Find columns that contain the "special" markers (not background)
    markers = {}
    for c in range(len(grid[0])):
        for r in range(len(grid)):
            if grid[r][c] != bg:
                markers[c] = True
                break

    # Transform: background → 2, markers preserved, BUT if a column contains markers,
    # those 0s become 1 (or become other marker colors if present in that column)
    output = []
    for r in range(len(grid)):
        new_row = []
        for c in range(len(grid[0])):
            val = grid[r][c]

            # If column has markers (non-background) and cell has marker color, preserve it
            # If column has markers and cell is background, convert to 2 by default
            # The marker's region affects the output

            if val == bg and c in markers:
                # Column has special markers. Check which markers in this column.
                col_marker_colors = set()
                for rr in range(len(grid)):
                    if grid[rr][c] != bg:
                        col_marker_colors.add(grid[rr][c])

                # If column has marker 1, background cells in this column become 1
                # Otherwise they become 2
                if 1 in col_marker_colors:
                    new_row.append(1)
                else:
                    new_row.append(2)
            elif val == bg:
                new_row.append(2)
            else:
                # Preserve marker colors
                new_row.append(val)
        output.append(new_row)

    return output
